    "answer": "Cardiac events from beginning of one heartbeat to beginning of next (duration ~0.8s at 75 bpm). Ventricular systole (0.3s): isovolumetric contraction, rapid ejection, reduced ejection. Ventricular diastole (0.5s): isovolumetric relaxation, rapid filling, diastasis, atrial systole.",
