    "section": "Respiratory System",
    "topic": "Mechanics of Respiration",
    "type": "Written",
    "year": 2024,
    "marks": null,
    "teacher": null,
    "answer": "Inspiration is active: Diaphragm contraction flattens domes, external intercostals elevate ribs, expanding thoracic volume and creating negative intrapleural pressure (-6 to -8 mmHg). Expiration in quiet breathing is passive recoil of lungs and chest wall.",
