    "text": "Name the extrinsic muscles of tongue? What is tongue tie? What is the safety muscle of tongue & why?",
    "subject": "Anatomy",
    "paper": "Paper-I",
    "group": "Group-B",
    "section": "Tongue",
    "topic": "Tongue & Ankyloglossia",
