    "year": 2023,
    "marks": null,
    "teacher": null,
    "answer": "Extrinsic muscles: Genioglossus, Hyoglossus, Styloglossus, Palatoglossus. Safety muscle is Genioglossus because bilateral contraction pulls tongue forward, preventing it from falling back and obstructing airway. Tongue tie is ankyloglossia.",
