    "text": "Name the hormones of thyroid gland. State the steps of biosynthesis of thyroid hormones. State the calorigenic action of thyroid hormone.",
    "subject": "Physiology",
    "paper": "Paper-II",
    "group": "Group-A",
    "section": "Thyroid Hormone",
    "topic": "Thyroid Biosynthesis",
    "type": "Written",
    "year": 2022,
    "marks": null,
    "teacher": null,
    "answer": "Biosynthesis steps: 1) Iodide trapping (NIS symporter), 2) Oxidation of iodide to iodine (TPO), 3) Organification of thyroglobulin (MIT & DIT formation), 4) Coupling (MIT + DIT -> T3, DIT + DIT -> T4), 5) Storage and endocytosis, 6) Proteolysis and release of free T3/T4 into circulation.",
