    "answer": "Regulators: Parathyroid hormone (increases Ca2+), Calcitriol (increases Ca2+ & phosphate absorption), Calcitonin (decreases Ca2+). Hypocalcemia (<7 mg/dL) causes increased neuromuscular excitability leading to carpopedal spasm, Trousseau's sign, and Chvostek's sign (tetany).",
