    "teacher": null,
    "answer": "Lipids are water-insoluble biomolecules soluble in non-polar organic solvents. Classified into simple (fats, oils, waxes), compound (phospholipids, glycolipids, lipoproteins), and derived (fatty acids, sterols, fat-soluble vitamins). Normal lipid profile: Total cholesterol < 200 mg/dL, LDL < 100 mg/dL, HDL > 40 mg/dL, Triglycerides < 150 mg/dL.",
